// ============================================================================
// APB SLAVE PHYSICAL SEQUENCES
//
// These sequences run only on apb_sequencer.
// Each sequence item tells the APB slave driver how to respond to one APB
// transfer generated by the DUT.
// ============================================================================


// ============================================================================
// 1. GENERIC APB RESPONSE SEQUENCE
// ============================================================================
class apb_response_sequence extends uvm_sequence #(apb_transaction);

    `uvm_object_utils(apb_response_sequence)

    rand int unsigned cfg_response_count;
    rand int unsigned cfg_wait_cycles;
    rand bit          cfg_inject_error;
    rand bit [31:0]   cfg_default_read_data;

    function new(string name = "apb_response_sequence");
        super.new(name);

        cfg_response_count    = 1;
        cfg_wait_cycles       = 0;
        cfg_inject_error      = 1'b0;
        cfg_default_read_data = 32'h0000_0000;
    endfunction

    virtual task body();

        apb_transaction req;
        int unsigned i;

        `uvm_info(
            "APB_SEQ",
            $sformatf(
                "Starting APB response sequence: COUNT=%0d WAIT=%0d ERROR=%0d",
                cfg_response_count,
                cfg_wait_cycles,
                cfg_inject_error
            ),
            UVM_LOW
        )

        for (i = 0; i < cfg_response_count; i = i + 1) begin

            `uvm_do_with(req, {

                wait_cycles == local::cfg_wait_cycles;

                inject_slverr == local::cfg_inject_error;

                response_data == local::cfg_default_read_data;

            })

        end

        `uvm_info(
            "APB_SEQ",
            "APB response sequence completed",
            UVM_LOW
        )

    endtask

endclass


// ============================================================================
// 2. APB WRITE/READ RESPONSE SEQUENCE
//
// Response #1 belongs to the APB WRITE created by the DUT.
// Response #2 belongs to the following APB READ.
// ============================================================================
class apb_write_read_response_sequence extends uvm_sequence #(apb_transaction);

    `uvm_object_utils(apb_write_read_response_sequence)

    rand int unsigned cfg_write_wait_cycles;
    rand int unsigned cfg_read_wait_cycles;

    rand bit          cfg_write_error;
    rand bit          cfg_read_error;

    rand bit [31:0]   cfg_default_read_data;

    function new(string name = "apb_write_read_response_sequence");
        super.new(name);

        cfg_write_wait_cycles = 0;
        cfg_read_wait_cycles  = 0;
        cfg_write_error       = 1'b0;
        cfg_read_error        = 1'b0;
        cfg_default_read_data = 32'h0000_0000;
    endfunction

    virtual task body();

        apb_transaction req;

        `uvm_info(
            "APB_WR_RD_SEQ",
            "Starting APB WRITE/READ response sequence",
            UVM_LOW
        )

        // --------------------------------------------------------------------
        // RESPONSE #1: AXI WRITE -> APB WRITE
        // --------------------------------------------------------------------
        `uvm_do_with(req, {

            wait_cycles == local::cfg_write_wait_cycles;

            inject_slverr == local::cfg_write_error;

            response_data == 32'h0000_0000;

        })

        // --------------------------------------------------------------------
        // RESPONSE #2: AXI READ -> APB READ
        // APB driver first checks its internal memory.  This value is only a
        // fallback when the addressed location has not been written before.
        // --------------------------------------------------------------------
        `uvm_do_with(req, {

            wait_cycles == local::cfg_read_wait_cycles;

            inject_slverr == local::cfg_read_error;

            response_data == local::cfg_default_read_data;

        })

        `uvm_info(
            "APB_WR_RD_SEQ",
            "APB WRITE/READ response sequence completed",
            UVM_LOW
        )

    endtask

endclass
